CREATE TABLE public.app_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, permissions text[] NOT NULL DEFAULT '{}', is_system boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.app_roles TO authenticated;
GRANT ALL ON public.app_roles TO service_role;
ALTER TABLE public.app_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, user_id uuid, role_id uuid NOT NULL REFERENCES public.app_roles(id), protected boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.security_audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, actor_email text NOT NULL, action text NOT NULL, target text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.security_audit_logs TO authenticated;
GRANT ALL ON public.security_audit_logs TO service_role;
ALTER TABLE public.security_audit_logs ENABLE ROW LEVEL SECURITY;
INSERT INTO public.app_roles(name, permissions, is_system) VALUES ('Admin', ARRAY['posts.create','posts.edit','posts.delete','slides.manage','analytics.view','overview.view','roles.manage','audit.view'], true);
INSERT INTO public.user_roles(email,user_id,role_id,protected) SELECT e.email,u.id,r.id,true FROM unnest(ARRAY['noorasadbd@gmail.com','zenithgtastore@gmail.com','ramim980124@gmail.com']) AS e(email) CROSS JOIN public.app_roles r LEFT JOIN auth.users u ON lower(u.email)=e.email WHERE r.name='Admin';
CREATE FUNCTION public.has_permission(p_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.user_roles ur JOIN public.app_roles r ON r.id=ur.role_id WHERE ur.email=lower(auth.jwt()->>'email') AND (ur.protected OR p_permission=ANY(r.permissions))) $$;
REVOKE ALL ON FUNCTION public.has_permission(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_permission(text) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_permission('roles.manage') $$;
CREATE POLICY "Read permitted roles" ON public.app_roles FOR SELECT TO authenticated USING(public.has_permission('roles.manage') OR EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.role_id=app_roles.id AND ur.email=lower(auth.jwt()->>'email')));
CREATE POLICY "Read own or managed assignments" ON public.user_roles FOR SELECT TO authenticated USING(email=lower(auth.jwt()->>'email') OR public.has_permission('roles.manage'));
CREATE POLICY "Read audit with permission" ON public.security_audit_logs FOR SELECT TO authenticated USING(public.has_permission('audit.view'));
CREATE FUNCTION public.my_permissions() RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT CASE WHEN ur.protected THEN ARRAY['posts.create','posts.edit','posts.delete','slides.manage','analytics.view','overview.view','roles.manage','audit.view'] ELSE r.permissions END FROM public.user_roles ur JOIN public.app_roles r ON r.id=ur.role_id WHERE auth.uid() IS NOT NULL AND ur.email=lower(auth.jwt()->>'email')), '{}'::text[]) $$;
CREATE FUNCTION public.manage_app_role(p_id uuid, p_name text, p_permissions text[]) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; oldrow jsonb; BEGIN
PERFORM pg_advisory_xact_lock(8972301);
IF NOT public.has_permission('roles.manage') THEN RAISE EXCEPTION 'Access denied'; END IF;
IF length(trim(p_name)) NOT BETWEEN 2 AND 40 OR p_name IS NULL OR p_permissions IS NULL OR NOT p_permissions <@ ARRAY['posts.create','posts.edit','posts.delete','slides.manage','analytics.view','overview.view','roles.manage','audit.view']::text[] THEN RAISE EXCEPTION 'Invalid role or permissions'; END IF;
IF p_id IS NULL THEN INSERT INTO public.app_roles(name,permissions) VALUES(trim(p_name),p_permissions) RETURNING id INTO rid;
ELSE SELECT to_jsonb(r) INTO oldrow FROM public.app_roles r WHERE id=p_id AND NOT is_system FOR UPDATE; IF oldrow IS NULL THEN RAISE EXCEPTION 'System role is protected or role not found'; END IF; UPDATE public.app_roles SET name=trim(p_name),permissions=p_permissions WHERE id=p_id RETURNING id INTO rid; END IF;
INSERT INTO public.security_audit_logs(actor_id,actor_email,action,target,details) VALUES(auth.uid(),lower(auth.jwt()->>'email'),CASE WHEN p_id IS NULL THEN 'role.created' ELSE 'role.updated' END,trim(p_name),jsonb_build_object('before',oldrow,'permissions',p_permissions)); RETURN rid; END $$;
CREATE FUNCTION public.assign_app_role(p_email text, p_role uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e text:=lower(trim(p_email)); oldrow jsonb; uid uuid; role_name text; BEGIN
PERFORM pg_advisory_xact_lock(8972301);
IF NOT public.has_permission('roles.manage') THEN RAISE EXCEPTION 'Access denied'; END IF;
IF e IS NULL OR length(e)>254 OR e !~ '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9.-]+\.[a-z]{2,}$' THEN RAISE EXCEPTION 'Invalid email'; END IF;
IF EXISTS(SELECT 1 FROM public.user_roles WHERE email=e AND protected) THEN RAISE EXCEPTION 'Original administrators are protected'; END IF;
SELECT to_jsonb(ur) INTO oldrow FROM public.user_roles ur WHERE email=e;
IF p_role IS NULL THEN DELETE FROM public.user_roles WHERE email=e; IF NOT FOUND THEN RAISE EXCEPTION 'Assignment not found'; END IF;
ELSE SELECT name INTO role_name FROM public.app_roles WHERE id=p_role; IF role_name IS NULL THEN RAISE EXCEPTION 'Role not found'; END IF; SELECT id INTO uid FROM auth.users WHERE lower(email)=e; INSERT INTO public.user_roles(email,user_id,role_id) VALUES(e,uid,p_role) ON CONFLICT(email) DO UPDATE SET role_id=excluded.role_id,user_id=excluded.user_id,updated_at=now(); END IF;
INSERT INTO public.security_audit_logs(actor_id,actor_email,action,target,details) VALUES(auth.uid(),lower(auth.jwt()->>'email'),CASE WHEN p_role IS NULL THEN 'access.revoked' ELSE 'role.assigned' END,e,jsonb_build_object('before',oldrow,'role',role_name)); END $$;
CREATE FUNCTION public.roles_security_data() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN
IF NOT public.has_permission('roles.manage') THEN RAISE EXCEPTION 'Access denied'; END IF;
SELECT jsonb_build_object('roles',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.is_system DESC,r.name),'[]') FROM public.app_roles r),'assignments',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',ur.id,'email',ur.email,'role_id',ur.role_id,'protected',ur.protected,'updated_at',ur.updated_at,'joined',u.id IS NOT NULL,'last_sign_in_at',u.last_sign_in_at) ORDER BY ur.protected DESC,ur.email),'[]') FROM public.user_roles ur LEFT JOIN auth.users u ON lower(u.email)=ur.email)) INTO result; RETURN result; END $$;
CREATE FUNCTION public.security_audit_page(p_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_permission('audit.view') THEN RAISE EXCEPTION 'Access denied'; END IF; IF p_offset<0 OR p_offset>100000 THEN RAISE EXCEPTION 'Invalid offset'; END IF; RETURN jsonb_build_object('total',(SELECT count(*) FROM public.security_audit_logs),'logs',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM (SELECT * FROM public.security_audit_logs ORDER BY created_at DESC,id DESC LIMIT 25 OFFSET p_offset)x)); END $$;
REVOKE ALL ON FUNCTION public.my_permissions(),public.manage_app_role(uuid,text,text[]),public.assign_app_role(text,uuid),public.roles_security_data(),public.security_audit_page(integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.my_permissions(),public.manage_app_role(uuid,text,text[]),public.assign_app_role(text,uuid),public.roles_security_data(),public.security_audit_page(integer) TO authenticated;
ALTER POLICY "admin insert" ON public.posts WITH CHECK(public.has_permission('posts.create'));
ALTER POLICY "admin update" ON public.posts USING(public.has_permission('posts.edit')) WITH CHECK(public.has_permission('posts.edit'));
ALTER POLICY "admin delete" ON public.posts USING(public.has_permission('posts.delete'));
ALTER POLICY "admin insert slides" ON public.hero_slides WITH CHECK(public.has_permission('slides.manage'));
ALTER POLICY "admin update slides" ON public.hero_slides USING(public.has_permission('slides.manage')) WITH CHECK(public.has_permission('slides.manage'));
ALTER POLICY "admin delete slides" ON public.hero_slides USING(public.has_permission('slides.manage'));
ALTER POLICY "public read active slides" ON public.hero_slides USING(is_active OR public.has_permission('slides.manage'));
ALTER POLICY "Admin inserts slider settings" ON public.hero_slider_settings WITH CHECK(public.has_permission('slides.manage'));
ALTER POLICY "Admin updates slider settings" ON public.hero_slider_settings USING(public.has_permission('slides.manage')) WITH CHECK(public.has_permission('slides.manage'));
ALTER POLICY "admin upload media" ON storage.objects WITH CHECK(bucket_id='media' AND (public.has_permission('posts.create') OR public.has_permission('posts.edit') OR public.has_permission('slides.manage')));
ALTER POLICY "admin read media" ON storage.objects USING(bucket_id='media' AND (public.has_permission('posts.create') OR public.has_permission('posts.edit') OR public.has_permission('slides.manage')));
ALTER POLICY "admin update media" ON storage.objects USING(bucket_id='media' AND (public.has_permission('posts.edit') OR public.has_permission('slides.manage'))) WITH CHECK(bucket_id='media' AND (public.has_permission('posts.edit') OR public.has_permission('slides.manage')));
ALTER POLICY "admin delete media" ON storage.objects USING(bucket_id='media' AND (public.has_permission('posts.delete') OR public.has_permission('slides.manage')));
ALTER POLICY "Admins read analytics sessions" ON public.analytics_sessions USING(public.has_permission('analytics.view'));
ALTER POLICY "Admins read analytics pageviews" ON public.analytics_pageviews USING(public.has_permission('analytics.view'));
ALTER POLICY "Admins read slide clicks" ON public.hero_slide_clicks USING(public.has_permission('analytics.view'));
DO $$ DECLARE f record; perm text; BEGIN FOR f IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('admin_analytics','admin_analytics_acquisition','admin_hero_slide_stats','dev_console_overview') LOOP perm:=CASE WHEN f.proname='dev_console_overview' THEN 'overview.view' ELSE 'analytics.view' END; EXECUTE replace(pg_get_functiondef(f.oid),'public.is_admin()',format('public.has_permission(%L)',perm)); END LOOP; END $$;
GRANT EXECUTE ON FUNCTION public.has_permission(text) TO anon;